<?php
declare(strict_types=1);
namespace App\Entity;
use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]
class Appointment { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private Tenant $tenant; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false)] private AppointmentResource $resource; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false)] private AppointmentType $type; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false)] private User $customer; #[ORM\Column] private \DateTimeImmutable $startsAt; #[ORM\Column] private \DateTimeImmutable $endsAt; #[ORM\Column(length:20)] private string $status='reserved'; #[ORM\Column(type:'text',nullable:true)] private ?string $customerNote; public function __construct(Tenant $tenant,AppointmentResource $resource,AppointmentType $type,User $customer,\DateTimeImmutable $start,\DateTimeImmutable $end,?string $note){$this->tenant=$tenant;$this->resource=$resource;$this->type=$type;$this->customer=$customer;$this->startsAt=$start;$this->endsAt=$end;$this->customerNote=$note;} public function getId():?int{return $this->id;} public function getResource():AppointmentResource{return $this->resource;} public function getType():AppointmentType{return $this->type;} public function getCustomer():User{return $this->customer;} public function getStartsAt():\DateTimeImmutable{return $this->startsAt;} public function getEndsAt():\DateTimeImmutable{return $this->endsAt;} public function getStatus():string{return $this->status;} public function cancel():void{$this->status='cancelled';} }
